namespace HMS.Application.Documents;

/// <summary>
/// Private file storage outside the web root. New files go to quarantine and are only readable after release.
/// Keys are generated by the server and never contain guest names or ID numbers.
/// </summary>
public interface IDocumentStorage
{
    Task WriteQuarantineAsync(string key, Stream content, CancellationToken ct);
    Task<Stream?> OpenQuarantineAsync(string key, CancellationToken ct);
    Task ReleaseAsync(string key, CancellationToken ct);
    Task<Stream?> OpenReleasedAsync(string key, CancellationToken ct);
    Task DeleteAsync(string key, CancellationToken ct);
    /// <summary>Every stored file, for restore checks. Released is false for files still in quarantine.</summary>
    IAsyncEnumerable<StoredFile> ListAsync(CancellationToken ct);
}

public sealed record StoredFile(string Key, bool Released);

public enum ScanOutcome
{
    Clean,
    Infected,
    /// <summary>The scanner could not give an answer (not configured, unreachable, error). The file stays quarantined.</summary>
    Error,
}

public sealed record ScanVerdict(ScanOutcome Outcome, string? Detail);

public interface IMalwareScanner
{
    string Name { get; }
    Task<ScanVerdict> ScanAsync(Stream content, CancellationToken ct);
}

/// <summary>Keyed HMAC used to make signature records tamper-evident.</summary>
public interface IDocumentSigner
{
    string Sign(string payload);
    bool Verify(string payload, string signature);
}

public sealed class DocumentOptions
{
    public const string SectionName = "Documents";

    /// <summary>Folder for private files. Must be outside the web root and backed up separately.</summary>
    public string StoragePath { get; set; } = "";
    public long MaxBytes { get; set; } = 10 * 1024 * 1024;
    /// <summary>Development only: treat files as clean when no scanner is configured. Never enable in production.</summary>
    public bool AllowUnscanned { get; set; }
    public string? ClamAvHost { get; set; }
    public int ClamAvPort { get; set; } = 3310;
    /// <summary>Optional dedicated key for signature HMACs. When empty a key is derived from the JWT signing key.</summary>
    public string? SignatureKey { get; set; }
}

/// <summary>Upload input from the API layer (keeps ASP.NET types out of the application layer).</summary>
public sealed record DocumentUpload(Stream Content, string FileName, string? DeclaredContentType, long Length);

public sealed record DocumentDownload(Stream Content, string FileName, string ContentType);
